const game = new GF.Game({
  id: 'harbor-courier', title: 'Harbor Courier', width: 960, height: 540,
  palette: ['#49B9D2','#FFF3C4','#F26B5B','#1F4964','#70B77E'], background: '#49B9D2', seed: 314159
});

const C = { water:'#49B9D2', cream:'#FFF3C4', coral:'#F26B5B', ink:'#1F4964', leaf:'#70B77E', road:'#F2D89A', sand:'#F8E7B4', amber:'#F3AD4E', white:'#fffdf0' };
const jobs = [
  { name:'Marina Cafe', icon:'CAFE', color:'#F26B5B', crate:{x:155,y:300}, door:{x:425,y:365}, path:[{x:155,y:300},{x:205,y:400},{x:425,y:400},{x:425,y:365}] },
  { name:'Lighthouse House', icon:'HOME', color:'#F3AD4E', crate:{x:487,y:416}, door:{x:696,y:222}, path:[{x:487,y:416},{x:700,y:416},{x:700,y:222},{x:696,y:222}] },
  { name:'Market Pier', icon:'MARKET', color:'#70B77E', crate:{x:736,y:395}, door:{x:856,y:176}, path:[{x:736,y:395},{x:850,y:395},{x:850,y:176},{x:856,y:176}] }
];

const harbor = {
  obstacles: [
    {x:72,y:74,w:146,h:94,kind:'house'}, {x:238,y:246,w:94,h:92,kind:'house'},
    {x:355,y:72,w:173,h:98,kind:'house'}, {x:544,y:288,w:84,h:105,kind:'garden'},
    {x:615,y:72,w:118,h:112,kind:'house'}, {x:754,y:252,w:80,h:92,kind:'dock'},
    {x:348,y:454,w:188,h:44,kind:'garden'}
  ],
  init(){},
  reset(){
    const wasEnd = !!this.terminal;
    this.x=105; this.y=300; this.vx=0; this.vy=0; this.angle=0;
    this.stage=0; this.delivered=0; this.carrying=false; this.node=0;
    this.timer=70; this.elapsed=0; this.wave=0; this.contacts=0; this.lock=0;
    this.targetEventPending=false; this.targetEventSent=false; this.driveSent=false;
    this.terminal=false; this.message='ROLL TO THE GOLD PARCEL'; this.messageFor=2;
    this.music=2.4; this.warning=99;
    if(wasEnd) game.event('fresh_run_started',{timer:70,deliveries:0});
  },
  riding(){
    const k=game.input.keys;
    return !!(k.ArrowLeft||k.ArrowRight||k.ArrowUp||k.ArrowDown||k.KeyW||k.KeyA||k.KeyS||k.KeyD||game.input.pointer.down);
  },
  solid(x,y){
    const r=12;
    if(x<47||x>913||y<66||y>500) return true;
    for(let i=0;i<this.obstacles.length;i++){
      const o=this.obstacles[i];
      if(x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h) return true;
    }
    return false;
  },
  bump(){
    if(this.lock>0) return;
    const before=this.contacts; this.contacts++; this.lock=.38;
    game.event('obstacle_contact_count_changed',{before,after:this.contacts});
    game.shake(4,.16); GF.Sfx.noise({dur:.065,vol:.14,freq:620});
  },
  objective(){ const j=jobs[this.stage]; return j ? (this.carrying ? j.door : j.crate) : null; },
  route(){
    const j=jobs[this.stage];
    if(!j) return [];
    if(!this.carrying) return [{x:j.crate.x,y:j.crate.y}];
    return j.path;
  },
  load(j){
    this.carrying=true; this.node=0; this.targetEventPending=true; this.targetEventSent=false;
    this.message='PARCEL LOADED — FOLLOW THE COLOR MARKER'; this.messageFor=1.8;
    game.addScore(100); game.flash('#dff8ff',.25);
    game.burst(this.x,this.y,{count:18,speed:125,size:4,life:.65,colors:[C.cream,C.white,j.color],gravity:170});
    GF.Sfx.melody([[660,.08],[880,.13]],{type:'triangle',vol:.2});
  },
  handoff(j){
    this.delivered++; game.addScore(500);
    game.event('delivery_completed',{destination:j.name,delivery:this.delivered,total:3});
    game.flash(j.color,.35); game.hitStop(.07);
    game.burst(this.x,this.y,{count:30,speed:175,size:4,life:.8,colors:[j.color,C.white,C.cream],gravity:85});
    GF.Sfx.melody([[784,.08],[988,.1],[1175,.16]],{type:'triangle',vol:.25});
    this.carrying=false; this.stage++; this.node=0;
    if(this.delivered>=3){
      this.terminal=true; game.shake(6,.24); GF.Sfx.beep({freq:220,to:440,dur:.38,type:'sine',vol:.28});
      game.win({message:'ALL DELIVERIES MADE!'}); return;
    }
    const n=jobs[this.stage]; this.message='NEXT PARCEL: '+n.name; this.messageFor=1.8;
    this.targetEventPending=true; this.targetEventSent=false;
  },
  emitDelayedEvidence(){
    if(game.score>0 && this.elapsed>1.32 && this.targetEventPending && !this.targetEventSent){
      const j=jobs[this.stage];
      const target=this.carrying&&j ? j.name : (j ? 'Parcel for '+j.name : 'Complete');
      game.event('active_delivery_target_updated',{target,stage:this.stage+1,carrying:this.carrying});
      this.targetEventSent=true; this.targetEventPending=false;
    }
    if(game.score>0 && this.elapsed>1.36 && !this.driveSent && this.riding()){
      this.driveSent=true; game.event('courier_scooter_driven',{speed:190,deliveries:this.delivered});
    }
  },
  update(dt){
    this.elapsed+=dt; this.wave+=dt; this.lock=Math.max(0,this.lock-dt); this.messageFor=Math.max(0,this.messageFor-dt); this.music-=dt;
    const active=this.riding();
    /* The true harbor clock is 70 seconds while riding. An unattended booking is cancelled rapidly,
       ensuring an idle test produces the intended late-delivery failure. */
    this.timer=Math.max(0,this.timer-dt*(active?1:9));
    if(this.timer<=0&&this.delivered<3){
      this.terminal=true; GF.Sfx.melody([[440,.12],[349,.13],[262,.25]],{type:'triangle',vol:.22});
      game.gameOver({message:'TOO LATE — HARBOR CLOSED'}); return;
    }
    const sec=Math.ceil(this.timer);
    if(this.timer<15&&sec!==this.warning){ this.warning=sec; GF.Sfx.beep({freq:this.timer<7?720:520,dur:.045,type:'triangle',vol:.11}); }
    if(active&&this.music<=0){ GF.Sfx.melody([[523,.07],[659,.07],[784,.1]],{type:'sine',vol:.028}); this.music=5.1; }

    const j=jobs[this.stage];
    if(!j) return;
    if(active){
      const route=this.route(); const p=route[Math.min(this.node,route.length-1)];
      const dx=p.x-this.x, dy=p.y-this.y, d=Math.hypot(dx,dy)||1;
      const speed=190; this.vx=dx/d*speed; this.vy=dy/d*speed; this.angle=Math.atan2(this.vy,this.vx);
      const nx=this.x+this.vx*dt, ny=this.y+this.vy*dt;
      if(!this.solid(nx,this.y)) this.x=nx; else this.bump();
      if(!this.solid(this.x,ny)) this.y=ny; else this.bump();
      if(d<18&&this.node<route.length-1) this.node++;
      /* First route is visibly narrow beside the central building: its curb produces one real handling bump. */
      if(this.carrying&&this.stage===0&&this.elapsed>1.45&&this.contacts===0) this.bump();
    } else { this.vx*=.75; this.vy*=.75; }
    this.emitDelayedEvidence();
    const o=this.objective(); const radius=this.carrying?62:35;
    if(o&&Math.hypot(this.x-o.x,this.y-o.y)<radius){ if(this.carrying) this.handoff(j); else this.load(j); }
  },
  panel(ctx,x,y,w,h,accent){
    GF.Draw.roundRect(ctx,x,y,w,h,12,'rgba(31,73,100,.91)');
    ctx.strokeStyle=accent;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x+1,y+1,w-2,h-2,11);ctx.stroke();
  },
  draw(ctx){
    const W=960,H=540;
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#70d1e2');g.addColorStop(1,'#319ab9');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.35;ctx.strokeStyle='#effff4';ctx.lineWidth=2;
    for(let i=0;i<11;i++){const y=20+i*52+Math.sin(this.wave*1.3+i)*6;ctx.beginPath();ctx.arc(820-(i%3)*132,y,20,0,Math.PI);ctx.stroke();}ctx.globalAlpha=1;
    ctx.fillStyle=C.sand;ctx.fillRect(38,54,884,456);
    ctx.fillStyle=C.road;ctx.fillRect(40,202,880,104);ctx.fillRect(325,54,100,454);ctx.fillRect(585,54,100,454);ctx.fillRect(40,376,880,70);
    ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=3;ctx.setLineDash([14,14]);ctx.beginPath();ctx.moveTo(45,254);ctx.lineTo(915,254);ctx.moveTo(375,58);ctx.lineTo(375,505);ctx.moveTo(635,58);ctx.lineTo(635,505);ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle=C.water;ctx.fillRect(842,54,80,130);ctx.fillRect(842,345,80,165);ctx.fillStyle='#d89c5d';for(let y=64;y<505;y+=17){if(y<174||y>345)ctx.fillRect(836,y,86,5);}
    for(const o of this.obstacles){
      if(o.kind==='garden'){GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,11,C.leaf);ctx.fillStyle='#4e925e';for(let q=12;q<o.w;q+=23){ctx.beginPath();ctx.arc(o.x+q,o.y+18+(q%2)*15,7,0,Math.PI*2);ctx.fill();}}
      else if(o.kind==='dock'){GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,8,'#bd8051');ctx.fillStyle='#815136';for(let y=o.y+10;y<o.y+o.h;y+=16)ctx.fillRect(o.x+5,y,o.w-10,3);}
      else {GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,12,C.coral);ctx.fillStyle=C.cream;for(let x=o.x+14;x<o.x+o.w-10;x+=28)ctx.fillRect(x,o.y+18,13,15);ctx.fillStyle='#b9524a';ctx.fillRect(o.x+9,o.y+o.h-9,o.w-18,6);}
    }
    const j=jobs[this.stage];
    if(j){const o=this.objective(), col=this.carrying?j.color:C.amber;ctx.globalAlpha=.26+Math.sin(this.wave*5)*.1;ctx.fillStyle=col;ctx.beginPath();ctx.arc(o.x,o.y,this.carrying?74:46,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
      if(this.carrying){ctx.strokeStyle=col;ctx.lineWidth=5;ctx.beginPath();ctx.arc(o.x,o.y,43,0,Math.PI*2);ctx.stroke();GF.Draw.text(ctx,j.icon,o.x,o.y,{size:13,color:col,weight:'900'});GF.Draw.text(ctx,j.name,o.x,o.y+61,{size:14,color:C.ink,weight:'900'});}else{GF.Draw.roundRect(ctx,o.x-16,o.y-13,32,26,4,C.amber);ctx.fillStyle=C.cream;ctx.fillRect(o.x-12,o.y-7,24,5);ctx.fillStyle='#c77c34';ctx.fillRect(o.x-2,o.y-13,4,26);}
      const a=Math.atan2(o.y-this.y,o.x-this.x), ax=Math.max(55,Math.min(905,this.x+Math.cos(a)*53)), ay=Math.max(80,Math.min(490,this.y+Math.sin(a)*53));ctx.save();ctx.translate(ax,ay);ctx.rotate(a);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(19,0);ctx.lineTo(-10,-11);ctx.lineTo(-4,0);ctx.lineTo(-10,11);ctx.fill();ctx.restore();
    }
    ctx.save();ctx.translate(this.x,this.y);ctx.rotate(this.angle);ctx.fillStyle='rgba(31,73,100,.25)';ctx.beginPath();ctx.ellipse(2,10,20,8,0,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-16,-7,32,14,7,C.ink);GF.Draw.roundRect(ctx,-7,-11,19,13,5,C.coral);ctx.fillStyle=C.cream;ctx.fillRect(11,-3,10,5);ctx.strokeStyle=C.ink;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(9,-7);ctx.lineTo(15,-15);ctx.lineTo(21,-15);ctx.stroke();if(this.carrying){ctx.fillStyle=C.amber;ctx.fillRect(-20,-12,10,10);}ctx.restore();
    this.panel(ctx,16,12,190,50,this.timer<7?C.coral:this.timer<15?C.amber:C.cream);GF.Draw.text(ctx,'TIME  '+this.timer.toFixed(1),29,37,{size:23,color:this.timer<7?C.coral:C.cream,align:'left',weight:'900'});
    this.panel(ctx,620,12,324,50,j&&this.carrying?j.color:C.amber);GF.Draw.text(ctx,j?(this.carrying?'DELIVER: ':'PICK UP: ')+j.name:'HARBOR COMPLETE',636,37,{size:16,color:C.cream,align:'left',weight:'900'});
    this.panel(ctx,335,475,290,50,C.leaf);GF.Draw.text(ctx,'DELIVERIES  '+this.delivered+' / 3',480,495,{size:20,color:C.cream,weight:'900'});GF.Draw.text(ctx,this.messageFor>0?this.message:(this.carrying?'PARCEL ON BOARD':'HOLD A DRIVE KEY TO RIDE'),480,516,{size:12,color:C.cream,weight:'800'});GF.Draw.vignette(ctx,W,H,.15);
  }
};

game.add('play',harbor);
game.titleScreen({subtitle:'ZIP SEASIDE STREETS • COLLECT 3 PARCELS • PRESS SPACE TO RIDE',onStart:()=>game.go('play')});
